preConditionHook:
// THE FINAL FLAG GIVES WAY THE WRONG WAY. Price closes through the
// COUNTERTREND side of the final-flag range: in a bull trend the flag's low
// gives out and the short fires; in a bear trend its high does and the long
// fires.
//
// V24-09 takes the break directly. R03-10 and R10-11 insist the market first
// breaks out WITH the trend, fails, comes back through the flag and out its
// other side -- the same trigger with a precondition, carried as the
// requirePriorBreakout input rather than as a second rule. R03-10's barbwire
// framing is just a short flagBars.
//
// THE FLAG WINDOW MOVES BACK when the prior breakout is required, and that is
// not cosmetic: measured over the same bars, the flag's own extreme would
// always be at or beyond any breakout inside it, so the with-trend breakout
// test could never be satisfied. With requirePriorBreakout on, the flag is the
// flagBars bars ENDING priorBreakoutWindow + 1 bars ago and the breakout is
// looked for in the priorBreakoutWindow bars since. With it off, flagOffset is
// 0 and the flag is simply the flagBars bars ending one bar ago -- and the
// breakout loop's k <= flagOffset guard is never true in that case, so it adds
// nothing to the unconditionally-true flags. That structure is used instead of an else
// branch because the loop must run either way, which also keeps the twin free
// of any dependence on short-circuiting.
//
// The flag extremes are scanned by hand rather than through a
// highest/lowest window so the offset can be a variable: seeded on the
// window's first bar and scanned with a STRICT comparison, which is what EL's
// Extremes does, and with el_gt / el_lt so the comparison carries the
// relational tolerance.
//
// FinalFlagCandidate is INLINED, read ONE BAR BACK (candPrev, mirrored at the
// top of the hook before it is recomputed): the flag has to have been a flag
// before this bar broke it. Its parts -- the always-in state machine and the
// bar-overlap count -- are the standing corpus decision and V07-01's
// definition; see FinalFlagCandidate for the reasoning and the MinList /
// MaxList note. A named Brooks setup inlines its parts, as the corpus does.
//
// Deepest bar touched: flagBars + priorBreakoutWindow.
candPrev = isCandidate;
allBull = true;
allBear = true;
for (int k = 0; k < (int)consecutiveBars; ++k) {
    rng = high[k] - low[k];
    if (el_le(close[k], open[k])) allBull = false;
    if (el_lt(close[k] - open[k], bodyFraction * rng)) allBull = false;
    if (el_gt(high[k] - close[k], tailFraction * rng)) allBull = false;
    if (el_gt(open[k] - low[k], tailFraction * rng)) allBull = false;
    if (el_ge(close[k], open[k])) allBear = false;
    if (el_lt(open[k] - close[k], bodyFraction * rng)) allBear = false;
    if (el_gt(close[k] - low[k], tailFraction * rng)) allBear = false;
    if (el_gt(high[k] - open[k], tailFraction * rng)) allBear = false;
}
flipped = false;
if (allBull && aiDir != 1) {
    aiDir = 1;
    aiBars = 0;
    flipped = true;
}
if (allBear && aiDir != -1 && flipped == false) {
    aiDir = -1;
    aiBars = 0;
    flipped = true;
}
if (flipped == false) aiBars = aiBars + 1;
ovCount = 0;
for (int k = 0; k < (int)flagBars; ++k) {
    ovBar = (high[k] < high[k + 1] ? high[k] : high[k + 1])
            - (low[k] > low[k + 1] ? low[k] : low[k + 1]);
    if (el_lt(ovBar, 0.0)) ovBar = 0.0;
    if (el_ge(ovBar, overlapThreshold * (high[k + 1] - low[k + 1]))) ovCount = ovCount + 1;
}
isCandidate = (aiDir != 0) && ((double)aiBars >= minTrendBars) && el_ge((double)ovCount, minOverlapFraction * flagBars);
flagOffset = 0;
if ((int)requirePriorBreakout != 0) flagOffset = (int)priorBreakoutWindow;
flagHigh = high[1 + flagOffset];
flagLow = low[1 + flagOffset];
for (int k = 2 + flagOffset; k <= (int)flagBars + flagOffset; ++k) {
    if (el_gt(high[k], flagHigh)) flagHigh = high[k];
    if (el_lt(low[k], flagLow)) flagLow = low[k];
}
brkUp = ((int)requirePriorBreakout == 0);
brkDn = ((int)requirePriorBreakout == 0);
for (int k = 1; k <= (int)priorBreakoutWindow; ++k) {
    if (k <= flagOffset && el_gt(high[k], flagHigh)) brkUp = true;
    if (k <= flagOffset && el_lt(low[k], flagLow)) brkDn = true;
}
revLong = candPrev && brkDn && el_gt(close[0], flagHigh);
revShort = candPrev && brkUp && el_lt(close[0], flagLow);
